def transform(grid):
    colors = sorted({v for row in grid for v in row if v != 0})
    blocks = []
    for color in colors:
        cells = [(r, c) for r, row in enumerate(grid) for c, v in enumerate(row) if v == color]
        r0 = min(r for r, c in cells)
        r1 = max(r for r, c in cells)
        c0 = min(c for r, c in cells)
        c1 = max(c for r, c in cells)
        blocks.append([[grid[r][c] for c in range(c0, c1 + 1)]
                       for r in range(r0, r1 + 1)])
    height = max(len(block) for block in blocks)
    output = [[0] * sum(len(block[0]) for block in blocks) for _ in range(height)]
    offset = 0
    for block in blocks:
        for r in range(len(block)):
            for c in range(len(block[r])):
                output[r][offset + c] = block[r][c]
        offset += len(block[0])
    return output
